/* ─── Map component ───────────────────────────────────────────── */

type Comune = (typeof COMUNI)[number];
type Luogo = Comune["luoghi"][number];

interface SiciliaMapProps {
  onSelectComune: (comune: Comune) => void;
  selectedComune: Comune | null;
}

function SiciliaMap({ onSelectComune, selectedComune }: SiciliaMapProps) {
  const [hovered, setHovered] = useState<Comune | null>(null);
  const [tooltipPos, setTooltipPos] = useState<[number, number, number]>([0, 0, 0]);
  const [isZoomed, setIsZoomed] = useState(true);
  const [urlPrefix, setUrlPrefix] = useState("");

  useEffect(() => {
    if (typeof window !== "undefined") {
      setUrlPrefix(window.location.pathname);
    }
  }, []);

  // Zoomed-in bounds (focusing on Sicani area: center ~362, 333)
  const zoomX = 150;
  const zoomY = 170;
  const zoomW = 420;
  const zoomH = 320;

  const currentViewBox = isZoomed
    ? `${zoomX} ${zoomY} ${zoomW} ${zoomH}`
    : `0 0 ${SVG_W} ${SVG_H}`;

  return (
    <div className="relative w-full h-full">
      {/* Zoom control button */}
      <button
        onClick={() => setIsZoomed(!isZoomed)}
        className="absolute top-4 right-4 z-10 bg-background/85 backdrop-blur-md hover:bg-background/95 text-foreground px-3.5 py-2 rounded-xl text-[11px] font-semibold flex items-center gap-2 shadow-lg ring-1 ring-foreground/10 transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] cursor-pointer"
        title={isZoomed ? "Mostra l'intera Sicilia" : "Focalizza sui Monti Sicani"}
      >
        {isZoomed ? (
          <>
            <ZoomOut size={14} className="text-accent" />
            <span>Mostra intera Sicilia</span>
          </>
        ) : (
          <>
            <ZoomIn size={14} className="text-accent" />
            <span>Focus area Sicani</span>
          </>
        )}
      </button>

      <motion.svg
        animate={{ viewBox: currentViewBox }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
        xmlns="http://www.w3.org/2000/svg"
        style={{ width: "100%", height: "100%", display: "block" }}
        aria-label="Mappa della Sicilia con i comuni dei Sicani"
      >
        {/* ── Ocean background ── */}
        <rect width={SVG_W} height={SVG_H} fill="#2b3445" rx="0" />

        {/* ── Subtle grid lines ── */}
        {[...Array(6)].map((_, i) => (
          <line
            key={`h${i}`}
            x1={0} y1={i * (SVG_H / 5)}
            x2={SVG_W} y2={i * (SVG_H / 5)}
            stroke="#8685FD" strokeOpacity="0.12" strokeWidth="0.5"
            vectorEffect="non-scaling-stroke"
          />
        ))}
        {[...Array(10)].map((_, i) => (
          <line
            key={`v${i}`}
            x1={i * (SVG_W / 9)} y1={0}
            x2={i * (SVG_W / 9)} y2={SVG_H}
            stroke="#8685FD" strokeOpacity="0.12" strokeWidth="0.5"
            vectorEffect="non-scaling-stroke"
          />
        ))}

        {/* ── Sicily island fill ── */}
        {/* Shadow / depth */}
        <path
          d={SICILY_SUBPATH_0}
          fill="none"
          stroke="#8685FD"
          strokeWidth="8"
          strokeLinejoin="round"
          opacity="0.08"
          transform="translate(3, 5)"
        />
        {/* Island body */}
        <path
          d={SICILY_SUBPATH_0}
          fill="#fdfcf7"
          stroke="none"
        />
        {/* Subtle inner terrain gradient effect */}
        <path
          d={SICILY_SUBPATH_0}
          fill={`url(${urlPrefix}#terrainGrad)`}
          opacity="0.45"
        />
        {/* Island outline (border) */}
        <path
          d={SICILY_PATH}
          fill="#8685FD"
        />
        {/* Tiny island fill */}
        <path
          d={SICILY_SUBPATH_2}
          fill="#f4e2ba"
        />

        {/* ── Gradient definitions ── */}
        <defs>
          <radialGradient id="terrainGrad" cx="32%" cy="45%" r="20%">
            <stop offset="0%" stopColor="#8685FD" stopOpacity="0.25" />
            <stop offset="100%" stopColor="#8685FD" stopOpacity="0" />
          </radialGradient>
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="3" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <filter id="markerShadow" x="-50%" y="-50%" width="200%" height="200%">
            <feDropShadow dx="0" dy="2.5" stdDeviation="3" floodColor="#8685FD" floodOpacity="0.22" />
          </filter>
          <clipPath id="sicilyClip" clipPathUnits="userSpaceOnUse">
            <path d={SICILY_SUBPATH_0} />
          </clipPath>
        </defs>

        {/* ── Città Metropolitana di Palermo border and label ── */}
        <g transform="translate(-10, -26)">
          <path
            d={PALERMO_PATH}
            fill="#ef4444"
            fillOpacity="0.04"
            stroke="#ef4444"
            strokeWidth={isZoomed ? 0.75 : 1.25}
            strokeDasharray={isZoomed ? "2.5 1.5" : "5 3"}
            vectorEffect="non-scaling-stroke"
          />

          {/* ── Label for Palermo Metropolitan Area ── */}
          <text
            x="350" y="230"
            textAnchor="middle"
            fontSize={isZoomed ? 4.5 : 7}
            fontFamily="Instrument Sans, system-ui"
            fontWeight="600"
            letterSpacing="0.12em"
            fill="#ef4444"
            opacity="0.85"
            style={{ transition: "font-size 0.3s ease, opacity 0.3s ease" }}
          >
            CITTÀ METROPOLITANA DI PALERMO
          </text>
        </g>

        {/* ── Province labels ── */}
        <text
          x="410" y="410"
          textAnchor="middle"
          fontSize={isZoomed ? 7.5 : 10}
          fontFamily="Instrument Sans, system-ui"
          fill="#7a9a5a"
          opacity={isZoomed ? 0.45 : 0.6}
          letterSpacing="0.1em"
          style={{ transition: "font-size 0.3s ease, opacity 0.3s ease" }}
        >
          AGRIGENTO
        </text>

        {/* ── Comune markers ── */}
        {COMUNI.map((comune) => {
          const [cx, cy] = project(comune.lat, comune.lng);
          const isCapofila = !!comune.capofila;
          const isAG = comune.provincia === "Agrigento";
          const isHovered = hovered?.nome === comune.nome;
          const isSelected = selectedComune?.nome === comune.nome;

          // Scale pin sizes down when zoomed in to maintain clean visuals
          const baseR = isCapofila ? 10 : 7;
          const sizeMultiplier = isSelected ? 1.35 : 1;
          const r = (isZoomed ? baseR * 0.65 : baseR) * sizeMultiplier;
          const color = isCapofila ? "#8685FD" : isAG ? "#6C63FF" : "#a78bfa";

          return (
            <g
              key={comune.nome}
              style={{ cursor: "pointer" }}
              onClick={() => onSelectComune(comune)}
              onMouseEnter={(e) => {
                setHovered(comune);
                const svg = (e.currentTarget as SVGGElement).closest("svg")!;
                const parentRect = svg.parentElement!.getBoundingClientRect();

                // Dynamic coordinate math that handles the viewBox offset and scaling
                const vX = isZoomed ? zoomX : 0;
                const vY = isZoomed ? zoomY : 0;
                const vW = isZoomed ? zoomW : SVG_W;
                const vH = isZoomed ? zoomH : SVG_H;

                const tx = ((cx - vX) / vW) * parentRect.width;
                const ty = ((cy - vY) / vH) * parentRect.height;
                setTooltipPos([tx, ty, (cx - vX) / vW]);
              }}
              onMouseLeave={() => setHovered(null)}
            >
              {/* Outer pulse ring for Capofila or Selected */}
              {(isCapofila || isSelected) && (
                <circle
                  cx={cx} cy={cy} r={isSelected ? (isZoomed ? 16 : 24) : (isZoomed ? 12 : 18)}
                  fill="none"
                  stroke="#8685FD"
                  strokeWidth={isSelected ? (isZoomed ? 1.5 : 2) : (isZoomed ? 1 : 1.5)}
                  opacity={isSelected ? 0.7 : 0.3}
                  className="animate-ping"
                  style={{ animationDuration: isSelected ? "1.5s" : "2s" }}
                />
              )}
              {/* Halo */}
              <circle
                cx={cx} cy={cy} r={r + (isHovered ? (isZoomed ? 3.5 : 5) : (isZoomed ? 2 : 3))}
                fill={color}
                opacity={isHovered || isSelected ? 0.3 : 0.15}
                style={{ transition: "r 0.15s ease, opacity 0.15s ease" }}
              />
              {/* Main dot */}
              <circle
                cx={cx} cy={cy} r={isHovered ? r + 2 : r}
                fill={color}
                stroke={isSelected ? "#ffffff" : "white"}
                strokeWidth={isCapofila || isSelected ? (isZoomed ? 2 : 3) : (isZoomed ? 1.2 : 2)}
                filter={`url(${urlPrefix}#markerShadow)`}
                style={{ transition: "r 0.15s ease" }}
              />
              {/* Star center for capofila */}
              {isCapofila && (
                <circle cx={cx} cy={cy} r={isZoomed ? 2 : 3} fill="white" opacity="0.8" />
              )}
            </g>
          );
        })}
      </motion.svg>

      {/* ── HTML Tooltip (outside SVG for better styling) ── */}
      {hovered && (
        <div
          className="pointer-events-none absolute z-10 bg-background rounded-2xl shadow-xl ring-1 ring-accent/20 px-4 py-3 min-w-[160px]"
          style={{
            left: tooltipPos[0] + 16,
            top: tooltipPos[1] - 20,
            transform: tooltipPos[2] > 0.6 ? "translateX(calc(-100% - 32px))" : "none",
          }}
        >
          <div className="text-[10px] font-bold uppercase tracking-widest text-accent mb-1">
            Prov. {hovered.provincia}
          </div>
          <div className="text-sm font-semibold text-foreground leading-tight">
            {hovered.nome}
          </div>
          {hovered.capofila && (
            <div className="mt-2 inline-block text-[9px] font-bold uppercase tracking-widest text-accent bg-accent/10 rounded-full px-2 py-0.5">
              Comune capofila
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ─── Luogo Carousel ──────────────────────────────────────────── */

function LuogoCarousel({ luogo }: { luogo: Luogo }) {
  // If we had multiple images, we'd use state. For now, it's just one image.
  const images = [luogo.immagine];
  const [currentIndex, setCurrentIndex] = useState(0);

  const next = () => setCurrentIndex((prev) => (prev + 1) % images.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);

  return (
    <div className="relative h-64 sm:h-72 w-full bg-foreground/5 overflow-hidden group">
      <AnimatePresence mode="wait">
        <motion.img
          key={currentIndex}
          src={images[currentIndex]}
          alt={luogo.nome}
          initial={{ opacity: 0, scale: 1.05 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.4 }}
          className="absolute inset-0 w-full h-full object-cover"
        />
      </AnimatePresence>
      <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/10 to-transparent" />
      
      {images.length > 1 && (
        <>
          <button onClick={prev} className="absolute left-4 top-1/2 -translate-y-1/2 size-8 rounded-full bg-black/30 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-sm hover:bg-black/50">
            <ChevronLeft size={18} />
          </button>
          <button onClick={next} className="absolute right-4 top-1/2 -translate-y-1/2 size-8 rounded-full bg-black/30 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-sm hover:bg-black/50">
            <ChevronRight size={18} />
          </button>
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-1.5">
            {images.map((_, i) => (
              <div key={i} className={`h-1.5 rounded-full transition-all ${i === currentIndex ? "w-4 bg-white" : "w-1.5 bg-white/50"}`} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

/* ─── Page ────────────────────────────────────────────────────── */

function TerritorioPage() {
  const [selectedComune, setSelectedComune] = useState<Comune | null>(null);
  const [selectedLuogo, setSelectedLuogo] = useState<Luogo | null>(null);

  const agComuni = COMUNI.filter((c) => c.provincia === "Agrigento");
  const paComuni = COMUNI.filter((c) => c.provincia === "Palermo");

  return (
    <div className="min-h-screen bg-background relative overflow-x-hidden">
      <SiteHeader />

      <main className="pt-24 pb-16">
        {/* Header */}
        <div className="max-w-7xl mx-auto px-6 mb-12">
          <span className="text-[11px] font-semibold uppercase tracking-[0.2em] text-accent mb-4 block">
            Il territorio
          </span>
          <h1 className="text-6xl md:text-7xl font-semibold tracking-tight leading-[1.02] text-balance mb-6">
            I <span className="text-accent italic font-normal">comuni</span> dei Sicani.
          </h1>
          <p className="text-lg text-ink-muted max-w-[52ch] leading-relaxed">
            Dodici comuni tra le province di Agrigento e Palermo, uniti da un
            territorio montano straordinario e da una vocazione agroalimentare
            autentica. Premi su un comune per esplorarne le località.
          </p>
        </div>

        {/* Map + sidebar */}
        <div className="max-w-7xl mx-auto px-6 flex flex-col lg:flex-row gap-6">
          {/* Map with viola glow halo */}
          <div className="flex-1 relative group">
            <div className="absolute -inset-1 bg-gradient-to-tr from-accent/30 via-accent/10 to-transparent rounded-[2.2rem] blur-2xl opacity-60 pointer-events-none" />
            <div
              className="relative rounded-[2rem] overflow-hidden ring-1 ring-foreground/10 shadow-2xl bg-[#1A1A1E]"
              style={{ height: "540px" }}
            >
              <SiciliaMap onSelectComune={setSelectedComune} selectedComune={selectedComune} />
            </div>
          </div>

          {/* Sidebar */}
          <div className="w-full lg:w-80 flex flex-col gap-5">
            {/* Legend */}
            <div className="bg-surface rounded-3xl p-6 border border-foreground/8 shadow-sm">
              <p className="text-[10px] font-bold uppercase tracking-[0.22em] text-ink-muted/70 mb-5">
                Legenda
              </p>
              <div className="space-y-3.5">
                <div className="flex items-center gap-3">
                  <div className="size-3.5 rounded-full bg-accent ring-4 ring-accent/20 flex-shrink-0" />
                  <span className="text-sm text-foreground font-medium">Comune capofila (Bivona)</span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="size-3 rounded-full bg-[#6C63FF] flex-shrink-0" />
                  <span className="text-sm text-foreground/80">Provincia di Agrigento</span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="size-3 rounded-full bg-[#a78bfa] flex-shrink-0" />
                  <span className="text-sm text-foreground/80">Provincia di Palermo</span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-6 h-0 border-t-2 border-dashed border-[#ef4444] flex-shrink-0" />
                  <span className="text-sm text-foreground/80">Confine Città Metr. Palermo</span>
                </div>
              </div>
            </div>

            {/* Agrigento chips */}
            <div className="bg-surface rounded-3xl p-6 border border-foreground/8 shadow-sm">
              <p className="text-[10px] font-bold uppercase tracking-[0.22em] text-ink-muted/70 mb-4">
                Prov. Agrigento
              </p>
              <div className="flex flex-wrap gap-2">
                {agComuni.map((c) => {
                  const isSelected = selectedComune?.nome === c.nome;
                  const isCapofila = !!c.capofila;
                  const base = "inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm transition-all cursor-pointer";
                  const cls = isCapofila
                    ? `${base} bg-accent text-white font-semibold border border-accent shadow-sm hover:shadow-md`
                    : isSelected
                      ? `${base} bg-accent/10 text-accent font-semibold border border-accent/30`
                      : `${base} bg-background text-foreground border border-foreground/10 hover:border-accent hover:text-accent`;
                  return (
                    <button key={c.nome} onClick={() => setSelectedComune(c)} className={cls}>
                      {c.nome}
                      {isCapofila && (
                        <span className="text-[8px] font-bold uppercase tracking-widest bg-white/20 text-white rounded px-1.5 py-0.5">
                          Capofila
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Palermo chips */}
            <div className="bg-surface rounded-3xl p-6 border border-foreground/8 shadow-sm">
              <p className="text-[10px] font-bold uppercase tracking-[0.22em] text-ink-muted/70 mb-4">
                Prov. Palermo
              </p>
              <div className="flex flex-wrap gap-2">
                {paComuni.map((c) => {
                  const isSelected = selectedComune?.nome === c.nome;
                  const base = "inline-flex items-center px-3 py-1.5 rounded-full text-sm transition-all cursor-pointer";
                  const cls = isSelected
                    ? `${base} bg-[#a78bfa]/10 text-[#7c6ad9] font-semibold border border-[#a78bfa]/40`
                    : `${base} bg-background text-foreground border border-foreground/10 hover:border-[#a78bfa] hover:text-[#7c6ad9]`;
                  return (
                    <button key={c.nome} onClick={() => setSelectedComune(c)} className={cls}>
                      {c.nome}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        </div>

        {/* Stats strip */}
        <div className="max-w-7xl mx-auto px-6 mt-12">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-5">
            {[
              { value: "12", label: "Comuni" },
              { value: "2", label: "Province" },
              { value: "~800 km²", label: "Area montana" },
              { value: "+140", label: "Produttori" },
            ].map((stat) => (
              <div
                key={stat.label}
                className="bg-surface rounded-[2rem] px-7 py-7 border border-foreground/8 shadow-sm hover:-translate-y-1 hover:shadow-md transition-all"
              >
                <div className="font-mono text-3xl md:text-4xl font-bold tracking-tight text-accent mb-2">
                  {stat.value}
                </div>
                <div className="text-[10px] font-bold uppercase tracking-[0.22em] text-ink-muted/70">
                  {stat.label}
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      {/* ── Side Drawer Panel overlay ── */}
      <AnimatePresence>
        {selectedComune && (
          <>
            {/* Backdrop */}
            <motion.div
              key="backdrop"
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.4 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedComune(null)}
              className="fixed inset-0 bg-black z-40 backdrop-blur-sm"
            />

            {/* Panel */}
            <motion.div
              key="panel"
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 28, stiffness: 220 }}
              className="fixed top-0 right-0 h-full w-full sm:w-[460px] bg-background border-l border-foreground/8 shadow-2xl z-50 flex flex-col"
            >
              {/* Header */}
              <div className="p-6 border-b border-foreground/5 flex items-center justify-between">
                <div>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-accent mb-1 block">
                    Prov. {selectedComune.provincia}
                  </span>
                  <h2 className="text-3xl font-bold tracking-tight text-foreground">
                    {selectedComune.nome}
                  </h2>
                </div>
                <button
                  onClick={() => setSelectedComune(null)}
                  className="size-8 rounded-full bg-foreground/5 hover:bg-foreground/10 text-foreground flex items-center justify-center transition-colors cursor-pointer"
                  aria-label="Chiudi finestra"
                >
                  <X size={16} />
                </button>
              </div>

              {/* Scrollable Content */}
              <div className="flex-1 overflow-y-auto p-6 space-y-6">
                <div>
                  <h3 className="text-xs font-semibold uppercase tracking-widest text-ink-muted mb-4">
                    Località consigliate
                  </h3>
                  <div className="space-y-5">
                    {selectedComune.luoghi.map((luogo) => (
                      <button
                        key={luogo.nome}
                        onClick={() => setSelectedLuogo(luogo)}
                        className="w-full text-left bg-surface rounded-2xl overflow-hidden border border-foreground/5 shadow-sm hover:shadow-lg hover:border-accent/20 transition-all duration-200 hover:scale-[1.01] flex flex-col cursor-pointer"
                      >
                        {/* Image */}
                        <div className="h-44 w-full relative overflow-hidden bg-foreground/5">
                          <img
                            src={luogo.immagine}
                            alt={luogo.nome}
                            className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"
                          />
                          <div className="absolute inset-0 bg-gradient-to-t from-black/30 to-transparent" />
                          <div className="absolute bottom-3 right-3 bg-white/10 backdrop-blur-sm rounded-lg px-2.5 py-1 text-white text-[10px] font-semibold flex items-center gap-1.5 border border-white/20">
                            <ExternalLink size={10} />
                            Scopri di più
                          </div>
                        </div>

                        {/* Details */}
                        <div className="p-5 flex flex-col gap-2">
                          <h4 className="font-bold text-lg text-foreground leading-snug">
                            {luogo.nome}
                          </h4>

                          <div className="flex items-center gap-1.5 text-xs text-accent font-semibold">
                            <MapPin size={12} className="flex-shrink-0" />
                            <span>{luogo.posizione}</span>
                          </div>

                          <p className="text-sm text-ink-muted leading-relaxed mt-1 line-clamp-2">
                            {luogo.descrizione}
                          </p>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      {/* ── Luogo Focus Overlay ── */}
      <AnimatePresence>
        {selectedLuogo && (
          <>
            <motion.div
              key="luogo-backdrop"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedLuogo(null)}
              className="fixed inset-0 bg-black/70 backdrop-blur-md z-[60]"
            />
            <motion.div
              key="luogo-panel"
              initial={{ opacity: 0, scale: 0.94, y: 24 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.94, y: 24 }}
              transition={{ type: "spring", damping: 28, stiffness: 240 }}
              className="fixed inset-x-4 top-8 bottom-8 sm:inset-x-auto sm:left-1/2 sm:-translate-x-1/2 sm:w-[520px] bg-background rounded-3xl shadow-2xl z-[70] flex flex-col overflow-hidden"
            >
              {/* Image Carousel */}
              <LuogoCarousel luogo={selectedLuogo} />

              {/* Close button */}
              <button
                onClick={() => setSelectedLuogo(null)}
                className="absolute top-4 right-4 z-10 size-9 rounded-full bg-black/40 backdrop-blur-sm hover:bg-black/60 text-white flex items-center justify-center transition-colors cursor-pointer"
                aria-label="Chiudi"
              >
                <X size={16} />
              </button>

              {/* Content */}
              <div className="flex-1 overflow-y-auto p-6 flex flex-col gap-5">
                <div>
                  <div className="flex items-center gap-1.5 text-xs text-accent font-semibold mb-2">
                    <MapPin size={12} className="flex-shrink-0" />
                    <span>{selectedLuogo.posizione}</span>
                  </div>
                  <h2 className="text-2xl font-bold tracking-tight text-foreground leading-snug">
                    {selectedLuogo.nome}
                  </h2>
                </div>

                <p className="text-sm text-ink-muted leading-relaxed">
                  {selectedLuogo.descrizione}
                </p>

                <p className="text-sm text-ink-muted leading-relaxed">
                  Questo luogo fa parte del patrimonio culturale e naturale dei Monti Sicani, un territorio unico che preserva tradizioni millenarie tra borghi medievali, paesaggi incontaminati e sapori autentici della Sicilia interna.
                </p>

                {/* Google Maps CTA */}
                <a
                  href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(selectedLuogo.posizione)}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="mt-auto flex items-center justify-center gap-2.5 bg-accent hover:bg-accent/90 text-white font-semibold text-sm px-6 py-4 rounded-2xl transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] shadow-lg shadow-accent/25"
                >
                  <svg viewBox="0 0 24 24" className="size-5 fill-current" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
                  </svg>
                  Ottieni indicazioni — Google Maps
                </a>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <SiteFooter />
    </div>
  );
}
